{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Absolute oral bioavailability was 57.8% in human subjects after a 0.1 mg oral dose compared with i.v. infusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Absolute bioavailability was 53% in healthy subjects across a 1–200 mg dose range.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "In fasting volunteers, aspirin (ASA) availability was estimated at about 17%, below the 20% threshold, but this was not an absolute bioavailability measurement.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct absolute oral bioavailability measurements in humans for multiple transferred molecules are 53–58%, well above the 20% threshold; the only numeric sub-threshold record is a non-absolute fasting aspirin estimate with provenance conflict, so high is better supported.",
  "evidence_gaps": [
    "Molecule 2 conflates aspirin and salicylate records; the fasting ASA value (~17%) is not an absolute bioavailability measurement and conflicts with absolute AUC comparisons.",
    "Molecule 4 provides only qualitative 'not good' oral bioavailability without a numeric threshold, so it is not decisive.",
    "Most positive absolute F records do not explicitly state fasted conditions, though none are fed-state."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

